<script setup lang="ts">
import { computed,ref } from 'vue';
import UiIcon from './UiIcon.vue';
import {maskMcpParameters,mcpReviewServices} from '../utils/mcp-review';
const props=defineProps<{data:any;actionable:boolean;busy:boolean}>();
const emit=defineEmits<{approve:[];reject:[feedback:string]}>();
const editing=ref(false),feedback=ref('');
const services=computed(()=>mcpReviewServices(props.data));
const pending=computed(()=>props.data.status===false);
const canApprove=computed(()=>props.data.allowed_decisions?.includes('approve'));
const canReject=computed(()=>props.data.allowed_decisions?.includes('reject'));
</script>
<template><section class="approval-card" :class="{processed:!pending}" aria-label="操作确认"><header><span class="approval-icon"><UiIcon :name="pending?'shield':'check'"/></span><div><h3>{{pending?'需要你确认这项操作':'操作确认已处理'}}</h3><p>{{pending?'确认前，工具会保持暂停。':'以下为当时提交的操作内容。'}}</p></div><span class="approval-state">{{actionable&&busy?'提交中…':pending?'等待确认':'已处理'}}</span></header><div class="approval-body"><p class="approval-purpose">{{services.length?'即将注册以下 MCP 服务。确认后，助手将继续执行注册。':'请核对操作内容和参数，再决定是否继续。'}}</p><article v-for="service in services" :key="service.name" class="approval-service"><h4><UiIcon name="connect"/>{{service.name}}</h4><dl><template v-if="service.type"><dt>连接方式</dt><dd>{{service.type}}</dd></template><template v-if="service.url"><dt>服务地址</dt><dd>{{service.url}}</dd></template><template v-if="service.command"><dt>启动命令</dt><dd>{{service.command}}</dd></template></dl></article><div v-if="!services.length" v-for="(action,index) in data.action_requests||[]" :key="index" class="approval-description"><strong>{{action.name||'待确认操作'}}</strong><p>{{action.description||'请展开参数查看具体内容。'}}</p></div><details><summary>查看完整操作参数<UiIcon name="chevron-down"/></summary><pre>{{JSON.stringify(maskMcpParameters(data.action_requests||[]),null,2)}}</pre></details><div v-if="actionable" class="approval-actions"><button v-if="canReject" class="approval-reject" :disabled="busy" @click="emit('reject','')">拒绝</button><button v-if="canReject" class="approval-edit" :disabled="busy" @click="editing=!editing">提出修改</button><button v-if="canApprove" class="approval-confirm" :disabled="busy" @click="emit('approve')"><UiIcon :name="busy?'clock':'check'"/>{{busy?'提交中…':'确认并继续'}}</button></div><form v-if="actionable&&editing" class="approval-feedback" @submit.prevent="emit('reject',feedback.trim())"><label>告诉助手需要怎样调整</label><textarea v-model="feedback" :disabled="busy" rows="3" placeholder="例如：修改服务名称或连接地址…" aria-label="修改意见"/><div><button type="button" :disabled="busy" @click="editing=false">取消</button><button type="submit" :disabled="busy||!feedback.trim()">提交修改</button></div><p>提交后，助手会调整方案，并再次等待你的确认。</p></form><p v-if="pending&&!actionable" class="approval-history">历史确认记录，请以当前会话的最新确认操作为准。</p></div></section></template>
